<?php
require_once __DIR__.'/../config/db.php';require_once __DIR__.'/../services/userService.php';require_once __DIR__.'/../includes/auth.php';$pdo=openDatabase();$u=requireLogin($pdo);requireRole($u,['Administrator']);$search=trim((string)($_GET['search']??''));$role=(string)($_GET['role']??'');$status=(string)($_GET['status']??'');if(!in_array($role,['','Student','Tutor','Administrator'],true)||!in_array($status,['','Active','Inactive'],true)){http_response_code(400);exit('Invalid filter');}$rows=searchUsers($pdo,$search,$role,$status);require __DIR__.'/../includes/header.php';require __DIR__.'/../includes/nav.php';?>
<main class="container py-4"><h1>Manage users</h1><form method="get" class="d-flex gap-2 mb-3"><input class="form-control" name="search" placeholder="Name or email" value="<?=htmlspecialchars($search,ENT_QUOTES,'UTF-8')?>"><select class="form-select" name="role"><?php foreach([''=>'All roles','Student'=>'Student','Tutor'=>'Tutor','Administrator'=>'Administrator'] as $v=>$label):?><option value="<?=$v?>" <?=$role===$v?'selected':''?>><?=$label?></option><?php endforeach;?></select><select class="form-select" name="status"><?php foreach([''=>'All statuses','Active'=>'Active','Inactive'=>'Inactive'] as $v=>$label):?><option value="<?=$v?>" <?=$status===$v?'selected':''?>><?=$label?></option><?php endforeach;?></select><button class="btn btn-primary">Search</button></form><?php if(!$rows):?><p>No matching users.</p><?php else:?><table class="table"><tr><th>Name</th><th>Email</th><th>Role</th><th>Status</th><th>Manage</th></tr><?php foreach($rows as $r):?><tr><td><?=htmlspecialchars($r['full_name'],ENT_QUOTES,'UTF-8')?></td><td><?=htmlspecialchars($r['email'],ENT_QUOTES,'UTF-8')?></td><td><?=htmlspecialchars($r['role'])?></td><td><?=htmlspecialchars($r['status'])?></td><td><a href="manage-user.php?user_id=<?=(int)$r['user_id']?>">Manage</a></td></tr><?php endforeach;?></table><?php endif;?></main><?php require __DIR__.'/../includes/footer.php';?>
